<?php
declare(strict_types=1);

$root=dirname(__DIR__);$files=['db/043_travel_day_operations.sql','app/Services/TripTravelOperationsService.php','travel-mode.php','api/travel-operations.php','assets/travel-mode.css','assets/travel-mode.js','travel-mode-offline.html','assets/travel-mode-offline.js','service-worker.php','bin/run-travel-watches.php','api/trip-command-center.php','partials/trip-command-center.php','assets/trip-command-center.js','partials/footer.php','app/bootstrap.php'];
foreach($files as $file){if(!is_file($root.'/'.$file)){fwrite(STDERR,"Missing Travel Day Operations file: {$file}\n");exit(1);}}
