$m=$read('db/043_travel_day_operations.sql');foreach(['operational_state',"ENUM('planning','booking','ready','traveling','completed')",'travel_mode_started_at','trip_operation_events','operational_status','terminal','gate','status_source','checkin_url',"'app_version','1.35'"] as $n){if(strpos($m,$n)===false){fwrite(STDERR,"Travel operations migration missing {$n}\n");exit(1);}}
