foreach(["'planning','booking','ready','traveling','completed'","'unknown','scheduled','on_time','delayed','cancelled','completed'",'user_id=? AND dream_trip_id=?'] as $n){if(strpos($s,$n)===false){fwrite(STDERR,"Travel operations lifecycle/ownership missing {$n}\n");exit(1);}}
$page=$read('travel-mode.php');foreach(['require_auth','verify_csrf()','Travel Day Operations','Start Travel Mode','Complete trip','Flight operations','Trip wallet','Agent supervision','Save offline itinerary','Status not connected','Live provider status','Local Agent','trip-bookings.php','next-moves'] as $n){if(strpos($page,$n)===false){fwrite(STDERR,"Travel Mode page missing {$n}\n");exit(1);}}
$api=$read('api/travel-operations.php');foreach(['require_auth','Cache-Control: private, no-store','TripTravelOperationsService','operations','Trip not found','temporarily unavailable'] as $n){if(strpos($api,$n)===false){fwrite(STDERR,"Travel operations API missing {$n}\n");exit(1);}}
$js=$read('assets/travel-mode.js');foreach(['vacationBrain.travelOffline.','data-save-offline','data-remove-offline','removeOffline','serviceWorker','60000','300000','Sensitive confirmation details were excluded'] as $n){if(strpos($js,$n)===false){fwrite(STDERR,"Travel Mode client missing {$n}\n");exit(1);}}if(strpos($js,'Math.random')!==false){fwrite(STDERR,"Travel Mode must use real state, not random activity.\n");exit(1);}
$offline=$read('assets/travel-mode-offline.js');foreach(['vacationBrain.travelOffline.','No confirmation codes','localStorage','Saved itinerary'] as $n){if(strpos($offline,$n)===false){fwrite(STDERR,"Offline Travel Mode missing {$n}\n");exit(1);}}
$sw=$read('service-worker.php');foreach(['vacation-brain-shell-v3','travel-mode-offline.html','travel-mode.php','caches.match(OFFLINE_TRAVEL)'] as $n){if(strpos($sw,$n)===false){fwrite(STDERR,"Service worker Travel Mode fallback missing {$n}\n");exit(1);}}if(strpos($sw,"caches.open(CACHE).then(c=>c.put(event.request")!==false){fwrite(STDERR,"Authenticated Travel Mode HTML must not be cached as the offline copy.\n");exit(1);}
