$commandApi=$read('api/trip-command-center.php');if(strpos($commandApi,'TripTravelOperationsService')===false||strpos($commandApi,'augmentCommandCenterSnapshot')===false){fwrite(STDERR,"Command Center API does not expose Travel Mode lifecycle.\n");exit(1);}
$commandServer=$read('partials/trip-command-center.php');foreach(['TripTravelOperationsService','augmentCommandCenterSnapshot','travel_mode_prominent','travel_mode_url','Travel Mode'] as $n){if(strpos($commandServer,$n)===false){fwrite(STDERR,"Command Center server render missing Travel Mode lifecycle {$n}\n");exit(1);}}
$commandJs=$read('assets/trip-command-center.js');foreach(['travel_mode_prominent','travel_mode_url','Travel Mode'] as $n){if(strpos($commandJs,$n)===false){fwrite(STDERR,"Command Center does not promote Travel Mode.\n");exit(1);}}
$footer=$read('partials/footer.php');foreach(['data-travel-mode-link','travel-mode.php?id=','Travel Mode · Live','Travel Mode · Ready'] as $n){if(strpos($footer,$n)===false){fwrite(STDERR,"Trip workspace Travel Mode link missing {$n}\n");exit(1);}}
$bootstrap=$read('app/bootstrap.php');if(strpos($bootstrap,"/Services/TripTravelOperationsService.php")===false){fwrite(STDERR,"TripTravelOperationsService is not loaded.\n");exit(1);}
$service=$read('app/Services/TripTravelOperationsService.php');if(strpos($service,"'confirmation_code'=>(string)")===false||strpos($service,"'privacy_note'=>'Offline copy excludes confirmation codes")===false){fwrite(STDERR,"Travel wallet/offline privacy boundary is not explicit.\n");exit(1);}
echo "Travel Day Operations contract OK\n";